sys_script_email.script:
(function runMailScript(/* GlideRecord */ current, /* TemplatePrinter */ template,
        /* Optional EmailOutbound */ email, /* Optional GlideRecord */ email_action,
        /* Optional GlideRecord */ event) {

	var instanceUrl = gs.getProperty('glide.servlet.uri');
	var tableName = current.getTableName();
	var sysId = current.getUniqueValue();

	// Link Instance
	var recordLink = instanceUrl + 'nav_to.do?uri=' + tableName + '.do?sys_id=' + sysId;
	// Link Workspace
	var workspaceLink = instanceUrl + 'x/fub/atendimento-escola-virtual/record/' + tableName + '/' + sysId;

	// HTML limpo usando tabela com suporte a largura fixa para e-mails
	var html = '';
	html += '<table border="0" cellspacing="0" cellpadding="0" style="margin: 25px 0;">';
	html += '  <tr>';

	// Botão Workspace (Azul)
	html += '    <td align="center" bgcolor="#007bff" style="border-radius: 4px; padding: 12px 20px;">';
	html += '      <a href="' + workspaceLink + '" target="_blank" style="font-size: 14px; font-family: Arial, sans-serif; color: #ffffff; text-decoration: none; font-weight: bold; display: inline-block;">Acessar no Workspace</a>';
	html += '    </td>';

	// // Espaçamento entre os botões
	// html += '    <td style="width: 10px;">&nbsp;</td>';

	// // Botão Interface Clássica (Cinza)
	// html += '    <td align="center" bgcolor="#6c757d" style="border-radius: 4px; padding: 12px 20px;">';
	// html += '      <a href="' + recordLink + '" target="_blank" style="font-size: 14px; font-family: Arial, sans-serif; color: #ffffff; text-decoration: none; font-weight: bold; display: inline-block;">Interface Clássica</a>';
	// html += '    </td>';

	html += '  </tr>';
	html += '</table>';

	template.print(html);

})(current, template, email, email_action, event);
